            "origin_leader_pid",
            origin_leader
                .map(|(p, _)| p as usize)
                .map(n)
                .unwrap_or_else(|| q("none")),
        ),
        (
            "origin_decided_while_partitioned",
            n(origin_decided_while_partitioned),
        ),
    ];
    report_resolution(mode, 11, &resolved, assigned_idx, decided, &extra);
}

